// Command fakeplugin is a minimal Mellifera scanner plugin used only by the
// internal/plugin tests. It is built to a temp binary by the test and launched
// as a real go-plugin subprocess so the Manager exercises the full handshake +
// gRPC + typed-Scanner round-trip (seam S5) against a live process. It lives
// under testdata/, which the go tool skips for ./... but an explicit
// `go build ./testdata/fakeplugin` builds (verified). It is never shipped.
package main

import (
	"context"
	"fmt"
	"io"
	"os"

	"github.com/hashicorp/go-hclog"
	goplugin "github.com/hashicorp/go-plugin"
	"google.golang.org/grpc"

	"github.com/mellifera/mellifera/pkg/sdk"
	pluginv1 "github.com/mellifera/mellifera/proto/mellifera/plugin/v1"
	scannerv1 "github.com/mellifera/mellifera/proto/mellifera/scanner/v1"
)

// The cookie pair MUST match the test's Manager Deps. go-plugin's client sets
// the key env var to the value when launching; the server validates it. (The
// itest joint harness boots THIS binary under cmd/mellifera's production
// Manager by putting the pair itself into the server subprocess's environment
// — go-plugin clients always append the parent's environment, so the pair
// reaches this process unchanged.)
const (
	cookieKey   = "MELLIFERA_TEST_COOKIE"
	cookieValue = "test-secret"
)

// stderrPayloadEnv is the scripted-stderr knob (the itest plugin-logs joint
// only; every other consumer leaves it unset and this main behaves exactly as
// before): when set, these exact bytes are written to this process's stderr
// in ONE Write BEFORE the go-plugin handshake begins, then serving proceeds
// normally. Test infrastructure only — the plugin contract (proto, SDK) is
// untouched.
const stderrPayloadEnv = "MELLIFERA_TEST_STDERR"

func main() {
	writeScriptedStderr()
	goplugin.Serve(&goplugin.ServeConfig{
		HandshakeConfig: goplugin.HandshakeConfig{
			ProtocolVersion:  1,
			MagicCookieKey:   cookieKey,
			MagicCookieValue: cookieValue,
		},
		// Two capability plugins share one gRPC server: the scanner capability
		// (sdk.ScannerPlugin registers scannerv1.ScannerServer) and the domain
		// Plugin service (pluginSvcPlugin registers pluginv1.PluginServer). The
		// Manager dispenses only the scanner; its domain Handshake/Shutdown hit
		// the Plugin service over the same connection.
		Plugins: goplugin.PluginSet{
			"scanner": &sdk.ScannerPlugin{Impl: fakeScanner{}},
			"plugin":  &pluginSvcPlugin{},
		},
		GRPCServer: goplugin.DefaultGRPCServer,
		// Silent server-side logger: go-plugin's default logs handshake
		// progress as JSON to this process's stderr, which the host pipes
		// into its per-plugin capture ring — the itest joint asserts the ring
		// carries ONLY the scripted payload bytes, so the logger is turned
		// off. Cosmetic for every other consumer: internal/plugin's tests
		// never read this process's stderr.
		Logger: hclog.New(&hclog.LoggerOptions{Level: hclog.Off, Output: io.Discard}),
	})
}

// writeScriptedStderr emits the MELLIFERA_TEST_STDERR payload (exact bytes,
// one Write) before the handshake. Failure aborts loudly — a half-written
// payload would silently break the joint's byte-identity assertion.
func writeScriptedStderr() {
	payload := os.Getenv(stderrPayloadEnv)
	if payload == "" {
		return
	}
	if _, err := os.Stderr.WriteString(payload); err != nil {
		fmt.Fprintf(os.Stderr, "fakeplugin: scripted stderr write failed: %v\n", err)
		os.Exit(1)
	}
}

// fakeScanner is the sdk.Scanner test implementation: Scan emits a fixed pair
// of discovered files (one with an ffprobe blob, one without), Identify echoes
// the file id + module type. Channel is buffered so Scan can fill + close; the
// full-emission close is reported as a clean terminal state before the close.
type fakeScanner struct{}

func (fakeScanner) Scan(_ context.Context, _ *scannerv1.ScanRequest) (*sdk.ScanStream, error) {
	ch := make(chan *scannerv1.DiscoveredFile, 2)
	ch <- &scannerv1.DiscoveredFile{FileId: "f1", RelativePath: "show/s01e01.mkv", FfprobeJson: []byte(`{"format":{"duration":"1800"}}`)}
	ch <- &scannerv1.DiscoveredFile{FileId: "f2", RelativePath: "show/s01e02.mkv"}
	ss := sdk.NewScanStream(ch)
	ss.End(nil)
	close(ch) // after End: the terminal report precedes the Files close
	return ss, nil
}

func (fakeScanner) Identify(_ context.Context, req *scannerv1.IdentifyRequest) (*scannerv1.IdentifyResult, error) {
	return &scannerv1.IdentifyResult{
		FileId:     req.GetFile().GetFileId(),
		MediaType:  req.GetModuleType(),
		ParserName: "fake",
		Confidence: 1.0,
	}, nil
}

// pluginSvcPlugin registers the domain Plugin service (Handshake/Health/
// Shutdown) on the shared gRPC server so the Manager's domain RPCs resolve.
type pluginSvcPlugin struct {
	goplugin.NetRPCUnsupportedPlugin
}

func (pluginSvcPlugin) GRPCServer(_ *goplugin.GRPCBroker, s *grpc.Server) error {
	pluginv1.RegisterPluginServer(s, pluginServer{})
	return nil
}

// GRPCClient is unused: this binary is always the server side. Satisfies the
// GRPCPlugin interface.
func (pluginSvcPlugin) GRPCClient(context.Context, *goplugin.GRPCBroker, *grpc.ClientConn) (interface{}, error) {
	return nil, nil
}

// pluginServer is the domain Plugin service stub.
type pluginServer struct {
	pluginv1.UnimplementedPluginServer
}

func (pluginServer) Handshake(_ context.Context, _ *pluginv1.HandshakeRequest) (*pluginv1.HandshakeResponse, error) {
	return &pluginv1.HandshakeResponse{PluginId: "fake", PluginVersion: "0.0.1", SdkVersion: "v1"}, nil
}

func (pluginServer) Health(_ context.Context, _ *pluginv1.HealthRequest) (*pluginv1.HealthResponse, error) {
	return &pluginv1.HealthResponse{Status: pluginv1.HealthResponse_SERVING}, nil
}

func (pluginServer) Shutdown(_ context.Context, _ *pluginv1.ShutdownRequest) (*pluginv1.ShutdownResponse, error) {
	return &pluginv1.ShutdownResponse{}, nil
}
